INSERT INTO `mdt_bolos` (`id`, `author`, `title`, `plate`, `owner`, `individual`, `detail`, `tags`, `gallery`, `officersinvolved`, `time`, `jobtype`) VALUES
	(482, 'Arthur Sifat', 'Pfister Comet S2', '40NGT022', 'Mayra Manha', '', '', '["Stolen Vehicle"]', '[]', '["(100 | Sifat) Arthur Sifat","(402 | Singham Singh Riot) Singham Singh Riot"]', '1724236059782', 'police'),
	(483, 'Harry Bosch', 'Used in Store robbery ', '26VZI717', 'Mr KALA', '', 'Incident number 4099', '[]', '[]', '["(460 | Harry Bosch) Harry Bosch","(354 | Mr Dominator) Mr  Dominator"]', '1724495463860', 'police'),
	(485, 'Squid   Flicker', 'USED IN ROBBARY', '5PF091SU', '', '', '', '[]', '[]', '["(409 | SQUiD FLiCkER) Squid   Flicker"]', '1725546174364', 'police'),
	(486, 'Abrar Nub', 'PDM', '05MIO309', 'mr kala', '', '', '[]', '[]', '[]', '1725549339229', 'police'),
	(487, 'IH ALPHA', 'Carring illegal items and weapon.', '2SZ539MZ', 'Lucifer Morningstar', '', '<p>Car Model: Virtue<br>Colour: Silver<br><br>Don not unseize this car untill cheif permission.<br><br></p><p><br></p>', '[]', '["https://media.discordapp.net/attachments/1275202559266652362/1281663924181274685/screenshot.jpg?ex=66dc8a0b&is=66db388b&hm=c6884ac726f256c5892db4b15d2d17dc335036c5f6614cf56d7748c06dd6415f&"]', '["(Sparkx [C-351]) Mr Sparkx","(100 | Sifat) Arthur Sifat","(150 | Steve Johnson) Steve Johnson"]', '1725643451051', 'police'),
	(488, 'Squid   Flicker', 'USED IN RABBARY', '9EC470AC', 'ALU MIYA', '', '', '[]', '[]', '[]', '1725702017285', 'police'),
	(489, 'Bagha Robin', '10-11 Avoid and 10-80', '27TZR898', 'Kalu SHELBY', 'Kalu SHELBY', '<p>Vehicle did not pull over after a 10-11 call for over speeding.</p><p>Led into a 10-80 and stopped at cat cafe for food.<br>The license plate was recorded at this point.</p><p>Immediately got back on vehicle and attempted escape. Successfully escaped later.&nbsp;</p><p>10-80 Led by: Arcan Walker with Bagha Robin</p><p>Action: To be put into impound for a long time advised by Alice Cooper.</p>', '[]', '[]', '[]', '1725740901886', 'police'),
	(491, 'Singham Singh Riot', 'stolen vehicle - BOLO - 10/3/2024', '48img679', 'john saint', '', 'owner\'s statement:  the owner reported the vehicle stolen from infront of burgershot.', '[]', '[]', '[]', '1727897516836', 'police'),
	(493, 'Bagha Robin', 'Personnel Bolo - 28 October, 2024', '', '', 'lalmanik', '<p><hr></p><p><span style="background-color: rgb(255, 255, 255);"><strong>Suspect:</strong> Lal Manik&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 255);"><strong>Look:</strong> Middle aged, Olive jacket, Blonde hair&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 255);"><strong>Birdy Handle:</strong> lalmanik</span></p><p><span style="background-color: rgb(255, 255, 255);"><strong>Phone Number:</strong> 5648583209&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 255);"><strong>Vehicles Involved:</strong> Multiple (+5)&nbsp;</span></p><p><hr></p><p><span style="background-color: rgb(255, 255, 255);"><strong>BOLO:</strong> Arrest on sight&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 255);"><strong>Special Request:</strong> Post his handcuffed picture on birdy\nReason: He taunted PD in birdy.&nbsp;</span></p><p><hr></p><p><strong style="background-color: rgb(255, 255, 255);">Incidents:&nbsp;</strong></p><p><span style="background-color: rgb(255, 255, 255);">27 October: 10-11 moved to 10-80\nTeal color vehicle reported stolen by owner.\nVehicle engaged in multiple 10-80 with police.\nSuspect evaded pursuit in all scenerios.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 255);">&nbsp;28 October: 911 call in front of PD, taunting police.\nWe acquired his phone number from here.\nHe said his name is lalmanik and he admitted to be a gangster in the city.\n10-13 on police cruiser tyres.\nUse of different vehicle (PDM) involved with person.</span></p><p><hr><span style="font-weight: bold; background-color: rgb(255, 255, 255);">Action Taken: </span><span style="background-color: rgb(255, 255, 255);">Driving license revoked after we acquired his name and contact details.</span></p>', '[]', '[]', '[]', '1730059981482', 'police');
