	(4155, 'Joy Hossain', 'FLEECA BANK- Charge - 8/29/2024', '\n      <p style="">\n          </p><p><font color="#ffffff" face="Arial, Helvetica, sans-serif" size="2"><strong><u>Summery:&nbsp;</u></strong></font></p>\n      <p></p><p><font color="#ffffff" face="Arial, Helvetica, sans-serif" size="2"><strong><u>Reporting officer ( Joy Hossain ) under LSPD department. I was patrolling with my car and suddenly I got a call on my phone. The call was from the bank manager. The bank manager told me that a number of people had broken into their bank lockers. Area ( MOTEL ) responded to bank Robbery. On arrival we found that there were 2 robbers and 1 hostage. There was white Car parked Infront of bank. LetÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢s talk to Robbers and find out more (There are 02 insides, 02 outsides.) Demanding the release of their hostages.</u></strong></font></p><p><font color="#ffffff" face="Arial, Helvetica, sans-serif" size="2"><strong><u><br></u></strong></font></p><p><font color="#ffffff" face="Arial, Helvetica, sans-serif" size="2"><strong><u>&gt;&gt; Demand: Free Passage , No tease For 6 Second&nbsp;&nbsp;</u></strong></font></p><p><font color="#ffffff" face="Arial, Helvetica, sans-serif" size="2"><strong><u>&gt;&gt; Commanding Officer: AIKOOOK SAN</u></strong></font></p><p><font color="#ffffff" face="Arial, Helvetica, sans-serif" size="2"><strong><u>&gt;&gt; Negotiation Officer:&nbsp; MAYRA MANHA</u></strong></font></p><p><font color="#ffffff" face="Arial, Helvetica, sans-serif" size="2"><strong><u>&gt;&gt; Gun Level: 1</u></strong></font></p><p><font color="#ffffff" face="Arial, Helvetica, sans-serif" size="2"><strong><u>&gt;&gt; Registration Plate:&nbsp;</u></strong><strong><u>81DQJ205</u></strong></font></p><p><font color="#ffffff" face="Arial, Helvetica, sans-serif" size="2"><strong><u>&gt;&gt; Car Owner: ANDREW DOLAROSA&nbsp;</u></strong></font></p>\n  ', '[]', '["(201 | Aikoook San) AIKOOOK SAN","(404 | Joy) Joy Hossain","(463 | MR PABLO) MR PABLO","(550 | Mayra) Mayra Manha","(NO CALLSIGN) Adam  Charles"]', '["LIGHT YAGAMI"]', '[]', '1724869932438', 'police'),
