	(4233, 'Rahul Khan', 'Joji Khan - Felony evading a peace officer - 9/30/', '\n      <p style="">\n          <p style="color: white;"><strong>ÃƒÂ°Ã…Â¸Ã¢â‚¬Å“Ã‚Â Summary:</strong></p>\n          <p style=""><em style=""><font color="#ffffff">I was doing code 1, Joji Khan called from his car I stopped . But suddenly 2 more cars came from behind me and try to&nbsp; boxed me. Then I felt that my life was in danger, so I called 78. Then when 78 came then asked Joji Khan to stop, but he pulled the car and ran away . That time he over speeding and started destroying the government property. When he realised that he could not escape, then came to the PD and surrendered.</font></em></p>\n          <p style="color: white;">&nbsp;</p>\n          <p style="color: white;"><strong>ÃƒÂ°Ã…Â¸Ã¢â‚¬ÂÃ‚Âª Weapons/Items Confiscated:</strong></p>\n          <p style="color: white;"><em>Ãƒâ€šÃ‚Â·&nbsp; GS-Pistol &amp; AK47</em></p>\n          <p style="color: white;">&nbsp;</p>\n          <p style="color: white;">-----</p>\n          <p style="color: white;"><strong style="background-color: var(--color-1);">ÃƒÂ°Ã…Â¸Ã¢â‚¬â„¢Ã‚Â¸ Fine: 5000</strong></p>\n          <p style="color: white;"><br></p>\n          <p style="color: white;"><strong>ÃƒÂ¢Ã…â€™Ã…Â¡ Sentence: 10</strong></p>\n          <p style="color: white;"><br></p>\n      </p>\n  ', '[]', '["(201 | NH Rana) Nh Rana","(242 | Rahul Khan) Rahul Khan"]', '[]', '["https://cdn.discordapp.com/attachments/1287469235785695303/1290025749658472531/image.png?ex=66faf59a&is=66f9a41a&hm=3ad5080487f00e75295a355d1e979c0819c639dbc7fc4669a44ccdb558dc3cb1&","https://cdn.discordapp.com/attachments/1287469235785695303/1290025514949673040/image.png?ex=66faf562&is=66f9a3e2&hm=bd49414063099c070268e89262622ce581002d5f17fed14eda8410213e059301&","https://cdn.discordapp.com/attachments/1287469235785695303/1290021087710548173/image.png?ex=66faf142&is=66f99fc2&hm=71fdf5370228719e10902d0ff1ccf56c1f58b38d79489f68944bfe9ce30b710f&"]', '1727716424444', 'police'),
	(4234, 'Harry Bosch', 'Name - Charge - 10/12/2024', '\n      <p style="">\n          <p style=""><span style="color: rgb(255, 255, 255);">Summery:&nbsp;</span></p><p style=""><span style="color: rgb(255, 255, 255);">Reporting officer (Joy Hossain) under LSPD department. I was patrolling with my car and suddenly I got a call on my phone. The call was from the bank manager. The bank manager told me that a number of people had broken into their bank lockers. Area (7185) responded to bank Robbery. On arrival we found that there were 2 robbers and 1 hostage. There was white car/Bike parked Infront of bank. LetÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢s talk to Robbers and find out more (There are 02 insides, 02 outsides.) Demanding the release of their hostages.</span></p><p style=""><span style="color: rgb(255, 255, 255);"><br></span></p><p style=""><span style="color: rgb(255, 255, 255);">&gt;&gt; Demand: Free Passage , No Heli captor , No spike , No tease For 6 Second&nbsp;&nbsp;</span></p><p style=""><span style="color: rgb(255, 255, 255);">&gt;&gt; Commanding Officer:</span></p><p style=""><span style="color: rgb(255, 255, 255);">&gt;&gt; Negotiation Officer:&nbsp;</span></p><p style=""><span style="color: rgb(255, 255, 255);">&gt;&gt; Hostage Name:&nbsp;</span></p><p style=""><span style="color: rgb(255, 255, 255);">&gt;&gt; Gun Level:&nbsp;</span></p><p style=""><span style="color: rgb(255, 255, 255);">&gt;&gt; Registration Plate:</span></p><p style=""><span style="color: rgb(255, 255, 255);">&gt;&gt; Car Owner:&nbsp;</span></p>\n      </p>\n  ', '[]', '[]', '[]', '[]', '1728670113286', 'police'),
