	(4281, 'Bagha Robin', 'Rockford Fleeca Robbery Charge - 11/11/2024', '\n      <p style="color: white;">\n          <p><strong>ðŸ“ Summary:</strong></p>\n          <p><em>After arrival on Fleeca Bank, we spotted two hostile personnel keeping one citizen on gunpoint. An officer was sent to negotiate with them for the terms of releasing hostage. They demanded free passage and no PD helicopter nearby in return for the hostage\'s safe release.</em></p>\n          <p>&nbsp;</p>\n          <p><strong>ðŸ§ Hostage:</strong> [Name Here]</p>\n          <p>&nbsp;</p>\n          <p><strong>ðŸ—„ï¸ Evidence Location:</strong> Stash # <span style="background-color: rgb(192, 80, 77);">4281</span></p>\n          <p>&nbsp;</p>\n          <p><strong>ðŸ”ª Weapons/Items Confiscated:</strong></p>\n          <p><em>Â· [Insert List Here]</em></p>\n          <p>&nbsp;</p>\n          <p>-----</p>\n          <p><strong style="background-color: var(--color-1);">ðŸ’¸ Fine:</strong></p>\n          <p>&nbsp;</p>\n          <p><strong>âŒš Sentence:</strong></p>\n          <p>-----</p>\n      </p>\n  ', '[]', '["(241) Bagha Robin","(242) El Magico","(320) Laizy Panda","(200) Nh Rana","(101 | Arcan) Arcan Walker","(100) EnRic Cooper"]', '["AK REXO"]', '["https://media.discordapp.net/attachments/1297563690970906666/1305286012066467850/screenshot.jpg?ex=673279d4&is=67312854&hm=78d14f780ad56245a7a9defc2c8e0c4df93c76d941b0dfd59f69aa8e6a83f6df&=&format=webp&width=680&height=383","https://media.discordapp.net/attachments/1297563690970906666/1305285627612364951/screenshot.jpg?ex=67327978&is=673127f8&hm=2003c433e179524bb54ea5b8851af78b32670fe665668604fb6fd8bd8af05888&=&format=webp&width=680&height=383","https://i.vgy.me/KZtS4Q.png","https://i.vgy.me/wKgcJs.png","https://i.vgy.me/m9pUAF.png","https://i.vgy.me/BHbXKQ.png","https://i.vgy.me/lU7LCf.png","https://r2.fivemanage.com/images/6eGYFzRs6tT8.webp"]', '1731275589653', 'police'),
