	(265, 'Alice Cooper', '', '', '', '[]', '[]', '[]', '[]', '1723933243899', 'police'),
	(266, 'James R Junior ', 'Car Theft', 'CAR THEIFT', '<p>&nbsp;PLATE :08pFC704&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Location :Stolen from vinewood cloth store&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; owner number: 3819081562&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Model :&nbsp;Pfister Comet S2<br></p>', '[]', '["(NO CALLSIGN) MR Aaron","(401) James R Junior "]', '["CRYO XD"]', '[]', '1724001263658', 'police'),
	(267, 'James R Junior ', 'Assult', 'Assult', '<p>Report by : cate cafe owner and workers : zeny zelda , Mr shaddy ,Mr Bunny , Tufan Ahmed. There was an assult on them by&nbsp; Mr RBN , cimson , koshai katappa, dollar inside cate Cafe.</p><p>Also, they got threats on the social media (Tweedle) by above mentioned people.</p>', '[]', '["(401 | James R Junior) James R Junior "]', '["Crimson Op","Mr Dollar","Mr Bunny","Mr Shady","Zany Zelda","Tufan Ahamed"]', '["https://cdn.discordapp.com/attachments/1078906192610476103/1274824501636366409/image.png?ex=66c3a856&is=66c256d6&hm=a3434adfa4b751812146b243b86c932fd6a22d79acd079485b19d27b6ca1f2b9&","https://cdn.discordapp.com/attachments/1078906192610476103/1274824252067024916/image.png?ex=66c3a81a&is=66c2569a&hm=1e6e03fd5f9c5c42ac872a639d990d1ca2ff1a9335977eb49e04644b408e7eb8&","https://cdn.discordapp.com/attachments/1078906192610476103/1274818769684004988/image.png?ex=66c3a2ff&is=66c2517f&hm=43424c1ab7d09f444b346f24ef7d4f905abbce1d263aa3c4eb0abc731368ff3d&"]', '1724010543331', 'police'),
	(268, 'MR  ISHAN', 'STORE ROBBERY', 'CAR INFORMATION. ', '<p><span style="background-color: rgb(255, 255, 255); font-family: &quot;Arial Black&quot;, Gadget, sans-serif;">OWNER NAME</span>:<span style="background-color: rgb(255, 255, 255);">&nbsp;</span><span style="font-family: &quot;Arial Black&quot;, Gadget, sans-serif; background-color: rgb(255, 255, 255);">BODY SOHEL</span></p><p><span style="font-family: &quot;Arial Black&quot;, Gadget, sans-serif; background-color: rgb(255, 255, 255);">CLAR CLASS</span>:<span style="background-color: rgb(255, 255, 255); font-family: &quot;Arial Black&quot;, Gadget, sans-serif;">SPORTS</span></p><p><span style="font-family: &quot;Arial Black&quot;, Gadget, sans-serif; background-color: rgb(255, 255, 255);">CAR MODEL</span>:<span style="background-color: rgb(255, 255, 255); font-family: &quot;Arial Black&quot;, Gadget, sans-serif;">COMET S2</span></p><p><span style="background-color: rgb(255, 255, 255); font-family: &quot;Arial Black&quot;, Gadget, sans-serif;">NUMBER PLATE:85IVA501</span></p><p><br></p>', '[]', '["(403 | MR ISHAN) MR  ISHAN","(506 | Harry Bosch) Harry Bosch"]', '[]', '[]', '1724057476616', 'police'),
	(269, 'El Magico', 'Mobile theft', 'Victim was infront of burgershot driving a car. Th', '', '[]', '[]', '["Mr Offset"]', '[]', '1724261755490', 'police'),
	(270, 'Arthur Sifat', 'We Got Three Injured People On Sea', 'Human Rescue', 'We got a report from a person and his name is: Kochi Da, he told us he got three injured person when he was catching fish on his board. he bring them into his house at Marina Drive and call us. and we rescue him.\n\nIdentified By,\n1. Mr RBN\n2. Mr Crimson\n\nRescued Person:\n1. Zany Zelda\n2. Mr Almir\n3. Mr Shady', '[]', '["(100 | Sifat) Arthur Sifat","(350 | Alice Cooper) Alice Cooper","(Sparkx [C-351]) Mr Sparkx","(461 | Mr Mahadi) Mr Mahadi"]', '["Zany Zelda","ALMIR X","Mr Shady"]', '["https://cdn.discordapp.com/attachments/1272273792969998429/1276284152597184572/Screenshot_63.png?ex=66c8f7be&is=66c7a63e&hm=2e7e3d9ae6ee65d9e50bfe9ca2197fca8c046c141b8a59844d057c7d5464e809&","https://cdn.discordapp.com/attachments/937769976830517319/1276281902881574913/screenshot.png?ex=66c8f5a5&is=66c7a425&hm=b87e2c2396b5c1355ce3804e33cbf34513de2e012f8785161b65516ecf66106a&","https://cdn.discordapp.com/attachments/937769976830517319/1276281855800250408/screenshot.png?ex=66c8f59a&is=66c7a41a&hm=bfe5b0a491dbe672dc42040a929b4f58637111c4b023d55f69572337ac414b6b&","https://cdn.discordapp.com/attachments/1272273792969998429/1276276168613429388/Screenshot_61.png?ex=66c8f04e&is=66c79ece&hm=2429c518036ffaaf18f009567368b91c1d6459877331328aff38ecf40bdafa6b&"]', '1724360313962', 'police'),
	(271, 'Squid   Flicker', '', '', '', '[]', '[]', '[]', '[]', '1724421216706', 'police'),
	(272, 'Abrar Nub', 'Stolen Vehicle Owner Alu MIya', 'Vehicle Theft', '<p><span style="color: rgb(255, 255, 255); background-color: rgb(0, 0, 0);">victim Parked his car out of the burger shot . Car num;</span><span style="color: rgb(255, 255, 255);">43ZKU043 Car model:Pfister Comet S2 . 2 officers chased them untill they went out of the city.</span></p>', '[]', '["(NO CALLSIGN) Squid   Flicker","(NO CALLSIGN) Abrar Nub"]', '[]', '[]', '1724424570155', 'police'),
	(273, 'Harry Bosch', 'THE DEMONS', '911 TO CODE RED', '<p><span style="color: rgb(255, 255, 255);"><br>A 911 call was made by Baby girl because she was threatned by some people. Police responded and so did dominator as backup afyer 10-78 was called. Suddenly someone in that chaos started brandishing his weapon and in response&nbsp; dominator gun pointed the guy to detain for such act. the mob started shouting and gun pointing at officers. they also cuffed dominator and situation turned into code red. many officers were injured<br>"ak bhai" and "baby girl" are interested to present themselves to court as witness. they blamed a group named demons who were wearing black color outfits. several people are under this investigation.<br>Criminals<br>KUMAR SHANU<br>KHANDAKAR MESSI<br>BLACK NINJA<br>JUNAYER KHAN<br>FOXY&nbsp;<br>FARHAN<br>JOKER DE SANTOS&nbsp;<br>ACE ALPHA<br>MR TATE</span></p>', '[]', '["(460 | Harry Bosch) Harry Bosch","(NO CALLSIGN) Squid   Flicker"]', '["Ak  Bhai","Baby Girl"]', '[]', '1724431202951', 'police'),
	(274, 'Harry Bosch', 'GD from burgershot', 'Suspected - Demons', '<p>a report from burgershot owner named remo: Some people gradually attack us and we belive we will be attacked soon. If so, the main suspects are a group called DEMONZ. And a guy namedjoker de santos who looks like a jester as well. We are in 750k loss beacuse of them and want justice.&nbsp;</p>', '[]', '["(406 | Harry Bosch) Harry Bosch","(353 | Khalid) Khalid Bin Walid"]', '["RAMO  XD"]', '[]', '1724614368412', 'police'),
	(275, 'Francesco Leo', 'Disresoecting Women', '', '<p>Faria is beaten by the owen of burger shot&nbsp;&nbsp;</p><p>Name: Lucifer</p>', '[]', '[]', '[]', '[]', '1724616855716', 'police'),
	(276, 'Harry Bosch', 'Prison Escort', 'Connected to 273', '<p><img src="https://media.discordapp.net/attachments/1275202559266652362/1277373553603379211/screenshot.jpg?ex=66ccee53&amp;is=66cb9cd3&amp;hm=d3794e3dea1b07e6492a6cfe43188671f1b2495c786133d21ddff3a4076bb026&amp;=&amp;format=webp&amp;width=830&amp;height=467" alt="Protocol" width=""><span style="background-color: rgb(255, 255, 255);">After arresting <span style="color: rgb(192, 80, 77);"><strong>BLACK NINJA</strong></span> in a code 5. <strong style="color: rgb(54, 96, 146);">Aikook sir</strong> relieved the criminal off of death sentence. In order to see the depth of <strong>The DEMONZ</strong> organization, <span style="color: rgb(31, 73, 125);"><strong>The investiagtion team</strong></span> decided to offer him Prison escort instead of <em><strong>$650k</strong></em>&nbsp; to show it as a bribery. The main reason behind this act was to see how much they are funded in such a short time.<br><strong>Incident</strong>: The prison escort was going well until we crossed the bridge near the DiAMOND CASINO, Several people heavily armed started shooting and pitting the escort. Some of them even were in pd vehicles. The escort reached the prison and was waiting for the prison guards to take the criminal and holding them off. The fight lasted an hour. Many of them were killed off and but at last black ninja was taken . We had less casualites than them and our unists were saved by our rescue team.&nbsp;<br>Further investigation is due</span></p>', '[]', '["(406 | Harry Bosch) Harry Bosch","(303 | Mr Dominator) Mr  Dominator","(353 | Khalid) Khalid Bin Walid","(251 I AIKOOOK) AIKOOOK SAN"]', '["BlacK Ninja"]', '["https://media.discordapp.net/attachments/1275202559266652362/1277373553603379211/screenshot.jpg?ex=66ccee53&is=66cb9cd3&hm=d3794e3dea1b07e6492a6cfe43188671f1b2495c786133d21ddff3a4076bb026&=&format=webp&width=830&height=467"]', '1724658366429', 'police'),
	(277, 'Joy Hossain', 'Shooting ', 'Shooting  at burger shop', '<p><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">A 911 call was made by Baby girl because she was threatned by some people. Police responded and so did dominator as backup afyer 10-78 was called. Suddenly someone in that chaos started brandishing his weapon and in response&nbsp; dominator gun pointed the guy to detain for such act. the mob started shouting and gun pointing at officers. they also cuffed dominator and situation turned into code red. many officers were injured</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">"ak bhai" and "baby girl" are interested to present themselves to court as witness. they blamed a group named demons who were wearing black color outfits. several people are under this investigation.</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">Criminals</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">KUMAR SHANU</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">KHANDAKAR MESSI</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">BLACK NINJA</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">JUNAYER KHAN</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">FOXY&nbsp;</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">FARHAN</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">JOKER DE SANTOS&nbsp;</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">ACE ALPHA</span><br style="color: rgb(255, 255, 255);"><span style="color: rgb(255, 255, 255);">MR TATE</span><br></p>', '[]', '[]', '[]', '[]', '1724689670699', 'police'),
	(278, 'Srikant Tiwari', 'Robbery', 'Store robbery', '<p>Store Robbery Near car wash</p><p>2 robbers inside</p><p>Hostage name - unknown(bandor)</p><p>Demand - free passage and no tease for 6 sec</p><p>car no - 60NVN726 (WHITE SEDAN)</p><p><br></p>', '[]', '["(556 I Srikant Tiwari) Srikant Tiwari","(555) Martin  Luther","(461 | Mr Mahadi) Mr Mahadi","(Sallu bhai) Sallu Bhai"]', '[]', '[]', '1724772614107', 'police'),
	(279, 'Martin  Luther', 'Robbery', 'Bank Robbery', '<p>Bank Robbery near Life Invader<br>Inside 2 robbers outside 2 robbers<br>demand-free passage, no tease for 6 sec<br>Hostage name : Body Sohel<br><br></p>', '[]', '[]', '["Body Sohel"]', '[]', '1724776726165', 'police'),
	(280, 'Harry Bosch', 'Complain', 'Srikant tiwari', '<p>3 days ago a Ekhasur rahmans vehicle was seized by srikant&nbsp; tiwari . and it was fined 10 lacs $</p>', '[]', '["(556 I Srikant Tiwari) Srikant Tiwari"]', '["Ekhlasur Rahman"]', '[]', '1724783688711', 'police'),
	(281, 'Srikant Tiwari', 'robbery', 'Bank Robbery', 'there is a 10-90 situation going opposide side of pinkage motel\nhostage - code 0\nrobbers - 2 inside 2 outside\ndemand - no tease for 6 sec outside from vichalle and free pasage\n vehichle - bhison(260YN251)\ncriminal involved - crospe husband', '[]', '["(NO CALLSIGN) Bagha Robin","(304 | Alice Cooper) Alice Cooper","(501 | elmagico) El Magico","(455| ALPHA) IH ALPHA","(556 I Srikant Tiwari) Srikant Tiwari"]', '[]', '[]', '1724794546831', 'police'),
	(282, 'Srikant Tiwari', 'Missing Vehicle', 'Car Stolen', 'The car (no - U688) has beed stolen from the garrage of PhillBox, which has beed reported by the owner herself named Miss. Mayrah\n', '[]', '["(508 | Garp) Mr Garp","(556 I Srikant Tiwari) Srikant Tiwari"]', '[]', '[]', '1725134935899', 'police'),
	(283, 'Harry Bosch', 'pd item stolen', 'ROBBERY', '', '[]', '[]', '[]', '[]', '1725218020936', 'police'),
	(284, 'El Magico', 'Missing Vehicle', 'Car Stolen Report', 'The victim Mr kala was sitting beside Main garage in his Car Ferrari SF90 . Then someone came to him and kicked out from his car and took his car.\nColor: Red and black\nlast 4 digit of car: 0309\n', '[]', '["(450 | el magico) El Magico"]', '["MR Kala"]', '[]', '1725381772114', 'police'),
	(285, 'Squid   Flicker', 'KIDNEY STEALING ', 'physical issue', '<p>Complainee: Senor Villain</p><p>Patient: Mr Shady</p><p>Suspect: 2 accompanied with Shady</p><p>EMS Explanation: Mr Shady was hit with a hammer by one of his 2 accomplices. So he was taken into citiscan room to check for brain damage.</p><p>EMS noticed blood in head and went for citiscan, and the report says upper brain cells have been damaged, and as a result the patient has forgotten some memories.</p><p>EMS says the whole scene is recorded in front parking CCTV and is viewable from senator\'s office after application.</p>', '[]', '[]', '[]', '[]', '1725567492708', 'police'),
	(286, 'IH ALPHA', 'Shotting', '', '<p>Suspect Name:&nbsp;<br>1. Andro Leo<br>2. Ariyan Kabir<br><br>Shooting on a civilian (Shadow Ski).</p>', '[]', '[]', '[]', '[]', '1725662324333', 'police'),
	(287, 'Abrar Nub', 'Missing Vehicle', 'Car stolen ', '<p>The victim ultima lepicc was sitting beside burgershot&nbsp; in his Pegassi zorruso . Then someone came to him and pointed gun, kicked out from his car and took his car. Color:Purple car:&nbsp;9YG738XZ<br></p>', '[]', '[]', '[]', '[]', '1725725550865', 'police'),
	(288, 'El Magico', 'Vehicle stolen from Pillbox', 'Vehicle Stolen', 'Car No: 7AZ316FD\nColor: Blue green\nOwner Name: Ariyan SK', '[]', '[]', '[]', '[]', '1725815778290', 'police'),
	(289, 'Abrar Nub', 'Random Shootout At legion square main garage', 'Random shootout', '<p>A guy [black colored t-shirt] in a civillian SUV started shooting randomly with level 1&nbsp; and killed 2 senior citizen and also shot at Mr dexx and tried to p.i.t his car. Reported by MR. Dexx&nbsp; Phone:7558408765</p>', '[]', '[]', '["Mr Dexx"]', '[]', '1725888689709', 'police'),
	(290, 'Mr Raiyan', 'vehicle stolen from burgershot.', 'vehicle num; 62MND146', '<p>This car is from Burger today 09/09/24 at 1 pm.&nbsp; One named (Child) he&nbsp; steals this vehicle&nbsp;Ferrari Ferrari SF90 . This report is made by the owner of this car sink filter.</p><p>{name;&nbsp; sink filter vehicle owner}<br></p><p>Report take Mr Raiyan (Trooper Master)</p>', '[]', '[]', '[]', '[]', '1725909613012', 'police'),
	(291, 'Steve Johnson', 'Vehicle Seized - T20 | Date: 10.09.2024', 'Vehicle Seized', '<p><span style="margin: 0px; padding: 0px; border: 0px; font-weight: 700; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces; color: rgb(255, 255, 255);"><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">Vehicle Name</span><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">: T20</span></span></p><p><span style="margin: 0px; padding: 0px; border: 0px; font-weight: 700; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;"><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px; color: rgb(255, 255, 255);">Color: Yellow</span></span></p><p><span style="margin: 0px; padding: 0px; border: 0px; font-weight: 700; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces; color: rgb(255, 255, 255);"><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">Number Plate</span><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">: 6VT599HL</span></span></p><p><span style="margin: 0px; padding: 0px; border: 0px; font-weight: 700; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces; color: rgb(255, 255, 255);"><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">Owner</span><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">: Mr Offset</span></span></p><p><span style="margin: 0px; padding: 0px; border: 0px; font-weight: 700; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces; color: rgb(255, 255, 255);"><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">Duration</span><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">: Seized until discussion with Higher Command</span></span></p><p><span style="margin: 0px; padding: 0px; border: 0px; font-weight: 700; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces; color: rgb(255, 255, 255);"><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">Seized By</span><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; font-family: inherit; vertical-align: baseline; outline: 0px;">: Steve Johnson | SASP Captain</span></span></p><p><span style="margin: 0px; padding: 0px; border: 0px; font-weight: 700; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; outline: 0px; white-space: break-spaces; color: rgb(255, 255, 255); vertical-align: baseline;"><em><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-family: inherit; outline: 0px; vertical-align: baseline;"></span></em></span></p><p><hr></p><p><span style="color: rgb(255, 255, 255); font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; white-space: break-spaces;"><strong><em>Debrief:</em></strong></span></p><p><span style="color: rgb(255, 255, 255); font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; white-space: break-spaces;"><strong>\n</strong>I (Steve Johnson) and my fellow officer (Harry Potter) was petrolling inside Los Santos. When we were at Legion, suddenly a Sports Car (Lamborghini) came speedly and on that time I turned on my Sirens to stop him, but he didn\'t stop. He went to the Legion Main Garage, and he parked that vehicle after that he got with T20 Yellow color vehicle and after that he flew with that then I chased that vehicle he flew towards the pinkage but when he noticed that I\'m giving him warning he turned U and came back towards main garage and he stopped. After stopping the vehilce he came out and started saying, "Are you drunk and addicted or not" Conteneously disrespecting all the officers and suddenly some of his friends started threatning that they will gonna kill all the officers, then my officer gave coms at Radio, As I was the commanding officer, I gave coms to arrest and take to the custody of that person who was driving Yellow in Color T20 Vehicle. Then he tried to ran but he couldn\'t after that they all started shootout on PD with Class 3 Weapon. </span></p>', '["Possesion of Weapon Class 3","Shootout"]', '["(150 | Steve Johnson) Steve Johnson","(502 Harry potter) Harry Potter"]', '[]', '["https://cdn.discordapp.com/attachments/1272273792969998429/1282809557831258132/FiveM_b3095_GTAProcess_KQ63VBpobM.png?ex=66e0b500&is=66df6380&hm=a9732412268762849b3fd045fd00ee30f71f9181f724cdc92d89c3abd18c84b5&"]', '1725915797234', 'police'),
