	(295, 'Professor Rado', 'Fracture Leg Operation ', 'Open Reduction with internal fixation', '<p><img src="https://cdn.discordapp.com/attachments/1287871021759860799/1287871076432482304/AdobeStock_463597910-1-1080x675.jpeg?ex=66f31ee8&amp;is=66f1cd68&amp;hm=a9df5250676dea796e1fa414ab82bcccf8f8a0bff7e7c0e7328f08a28e9e2efd&amp;" style="background-color: var(--color-1);" alt="" width=""><img src="https://cdn.discordapp.com/attachments/1287871021759860799/1287871076432482304/AdobeStock_463597910-1-1080x675.jpeg?ex=66f31ee8&amp;is=66f1cd68&amp;hm=a9df5250676dea796e1fa414ab82bcccf8f8a0bff7e7c0e7328f08a28e9e2efd&amp;" style="background-color: var(--color-1);" alt="" width=""><img src="https://media.discordapp.net/attachments/1275202559266652362/1287870961013751818/screenshot.jpg?ex=66f31ecc&amp;is=66f1cd4c&amp;hm=74e9afa25477ab00e5d0c2309179440920bede2ba7b851bb73eda3f5dd6e1445&amp;" style="background-color: var(--color-1);" alt="" width=""><span style="background-color: var(--color-1);">My patient, an police officer, had been admitted to the hospital. After Operation now he is in bed rest.</span></p><p><span style="background-color: var(--color-1);">Threatment&nbsp; by&nbsp;<br>Dr. Rado&nbsp;<br>Dr, Villain<br>Dr. Gullu</span></p>', '[]', '[]', '[]', '[]', '1727122515097', 'ambulance'),
