	(305, 'Laizy Panda', 'Attempt to murder ', 'F.I.R', '<p><span style="margin: 0px; padding: 0px; border: 0px; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;">SASP Report</span><span style="margin: 0px; padding: 0px; border: 0px; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;">\n\nDate</span><span style="margin: 0px; padding: 0px; border: 0px; font-family: &quot;gg sans&quot;, &quot;Noto Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif, &quot;Apple Symbols&quot;; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;">: 21.10.2024</span><br><br><br>&nbsp;Debrief :&nbsp;Today,&nbsp; Mr. Raj received death threat&nbsp; at main garage and he was kidnapped.&nbsp; They took him to a duplex mansion under garage at rockford. They scared him in different way and beat him badly.He suspects three person behind this incident.&nbsp; The suspect was wearing a light blue jacket, black face mask, and they carried class three weapon. they wearing high table logo vest.<br>they used sliver car animated car<br>they took&nbsp; phone from raj</p>', '[]', '["(333 | panda) Laizy Panda","(332 | Mufasa) MR MUFASA"]', '["IM RAJ"]', '[]', '1729532875253', 'police'),
	(306, 'Harry Bosch', 'Mr RBN', 'Use of class 3 - attemp to murder', '240/10 at 3 am mr rbn and another unknown person has been seen with thompson near little seoul shooting at several pther people. evidence taken by bagha robin', '[]', '["(250 | Bagha Robin) Bagha Robin"]', '[]', '["https://media.discordapp.net/attachments/1287469235785695303/1298392692539134094/image.png?ex=671a0eac&is=6718bd2c&hm=822f6ecef2aff935327266a9569daacbe85de60d278deb56907f719f6886cb00&=&format=webp&quality=lossless&width=1101&height=701"]', '1729707258854', 'police'),
	(307, 'Steve Johnson', 'Power Gamer | (Expired)', 'Arrest Warrant', '<p><span style="color: rgb(255, 255, 255);"><strong>San Andreas Police Department</strong><br><strong>Warrant Number:</strong> SAPD-2023-307<br><strong>Date Issued:</strong> October 25, 2023<br><strong>Time Issued:</strong> 01:30 AM<br>Warrant Duration: 3 Days, Ended- 29 October 11:59PM</span></p><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>ISSUED BY:</strong><br>Steve Johnson<br>SASP Trooper Captain</span></p><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>SUBJECT:</strong><br>Raven2x (aka Power Gamer)<br><strong>TWITTER HANDLE:</strong> @raven2x</span></p><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>CHARGE:</strong><br>Criminal Threat - Violation of Penal Code Section 1022. Its a infraction but will be counted as Felony as he threatened the doctors multiple times</span></p><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>DESCRIPTION OF OFFENSE:</strong><br>On October 24, 2023, at approximately 12:00 PM, the subject posted the following tweet:<br>"Pillbox Under Control"</span></p><p><span style="color: rgb(255, 255, 255);">This message is interpreted as a potential criminal threat, posing a risk to public safety and potentially inciting panic within the community, particularly regarding the Pillbox Hill area.</span></p><p><hr></p><p><strong style="color: rgb(255, 255, 255);">EVIDENCE:</strong></p><ul><li><span style="color: rgb(255, 255, 255);">Screenshot of the tweet dated October 25, 2023</span></li><li><span style="color: rgb(255, 255, 255);">User identification from Twitter confirming the account is operated by the subject, raven2x (aka Power Gamer)</span></li><li><span style="color: rgb(255, 255, 255);">Contextual analysis indicating potential for public alarm</span></li></ul><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>LOCATION OF SUBJECT: Mount Zona Hospital</strong><br>Tweeted from: Legion Square</span></p><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>AUTHORIZATION:</strong><br>This warrant authorizes the San Andreas Police Department to arrest the individual, raven2x (aka Power Gamer), and to seize any electronic devices or materials relevant to the criminal threat.&nbsp;</span></p><p><span style="color: rgb(255, 255, 255);"><strong>ISSUED BY:</strong><br>Steve Johnson<br>SASP Trooper Captain<br>San Andreas Police Department</span></p>', '["arrest warrant"]', '["(106 | Steve Johnson) Steve Johnson","(252 | el magico) El Magico","(250 | Bagha Robin) Bagha Robin","(100 | EnRic Cooper) EnRic Cooper","(201 | NH Rana) Nh Rana","(342 | Garp) Mr Garp","(260 | Mr. Ryzen) Mr Ryzen","(333 | panda) Laizy Panda","(301) Harry Dexter"]', '[]', '["https://i.vgy.me/xp9ZhU.png","img/not-found.webp"]', '1729806191470', 'police'),
	(308, 'Laizy Panda', 'Distributing & promoting suspicious medicine', 'complaint', '<p><span style="font-family: &quot;Arial Black&quot;, Gadget, sans-serif;">Date&nbsp; &nbsp; &nbsp; : 04-11-2024<br>Debrief :&nbsp;</span><span style="font-family: &quot;Comic Sans MS&quot;, Textile, cursive, sans-serif;"><span style="background-color: var(--color-1); margin: 0px; padding: 0px; border: 0px; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;">A woman named Quinzel claims to be a scientist</span><span style="background-color: var(--color-1); margin: 0px; padding: 0px; border: 0px; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;">.  He is distributing a medicine of his own invention to the general public without permission and forcefully pushing it into people</span><span style="background-color: var(--color-1); margin: 0px; padding: 0px; border: 0px; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;">. even they tried to push their suspicious medicine to police, chief Mr. Rana sir took a sample from them for testing purpose.\nThe woman was accompanied by a man who claimed imself to be a businees partner. \n\nSuspect 01 ; miss quinzel, Contact number : </span></span><span style="background-color: var(--color-1); font-family: &quot;Comic Sans MS&quot;, Textile, cursive, sans-serif; white-space: break-spaces;">6021866837\nSuspect 02 : Jason trujillo, contact number : </span><span style="background-color: var(--color-1); font-family: &quot;Comic Sans MS&quot;, Textile, cursive, sans-serif; white-space: break-spaces;">9073591350</span></p>', '[]', '["(200) Nh Rana","(301) Harry Dexter","(241) Bagha Robin","(320) Laizy Panda","(321) MR MUFASA","(253 | Mr Ak) Mr Ak"]', '["MISS Quinzel","Jason Trujillo"]', '["https://files.catbox.moe/33j6mb.png"]', '1730656969573', 'police'),
	(309, 'Nh Rana', 'Miss Quinzel', 'Arrest Warrant', '<p><strong style="color: rgb(255, 255, 255);">San Andreas Police Department</strong><br><strong style="color: rgb(255, 255, 255);">Warrant Number:</strong><font color="#ffffff">&nbsp;SAPD-2024-308</font><br><strong style="color: rgb(255, 255, 255);">Date Issued:</strong><font color="#ffffff">&nbsp;November&nbsp;07, 2024</font><br><strong style="color: rgb(255, 255, 255);">Time Issued:</strong><font color="#ffffff">&nbsp;12:30 AM</font><br><font color="#ffffff">Warrant Duration: 5 Days, Ended- 12 November&nbsp;11:59PM</font></p><p><hr></p><p><strong style=""><span style="color: rgb(255, 255, 255);">ISSUED BY: </span><span style="color: rgb(84, 141, 212);">NH Rana&nbsp;</span></strong><br><font color="#ffffff">Chief Of Los Santos Police Department</font></p><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>SUBJECT: Distributing &amp; promoting illegal morphine</strong><br></span></p><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>CHARGE:<span style="font-family: &quot;Arial Black&quot;, Gadget, sans-serif;"><br></span></strong><span style="font-family: Tahoma, Geneva, sans-serif;"><span style="font-size: 16px; white-space: break-spaces; background-color: var(--color-1);">1. Distribution of illegal substances\n</span>2. Endangering public safety<br><span style="background-color: var(--color-1); margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px;">3.&nbsp;</span><span style="background-color: var(--color-1); margin: 0px; padding: 0px; border: 0px; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;">Assault </span><span style="background-color: var(--color-1); margin: 0px; padding: 0px; border: 0px; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;">(forcefully administering suspicious medicine</span><span style="background-color: var(--color-1); margin: 0px; padding: 0px; border: 0px; font-size: 16px; vertical-align: baseline; outline: 0px; white-space: break-spaces;">).\n</span>4. Attempting to distribute suspicious substance to law .<br></span></span></p><p><hr></p><p style="text-align: justify;"><strong style="color: rgb(255, 255, 255); background-color: var(--color-1);">DESCRIPTION OF OFFENSE:<span style="font-family: Tahoma, Geneva, sans-serif;">&nbsp;</span></strong></p><p><span style="font-family: Tahoma, Geneva, sans-serif;"><p style="text-align: justify;"><span style="background-color: var(--color-1); color: rgb(255, 255, 255);"><span style="font-size: 16px; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px; white-space: break-spaces; background-color: var(--color-1);">A woman named Quinzel claims to be a scientist</span><span style="font-size: 16px; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px; white-space: break-spaces; background-color: var(--color-1);">. </span></span><span style="color: rgb(255, 255, 255); font-size: 16px; white-space: break-spaces; background-color: var(--color-1);">The woman was accompanied by a man who claimed imself to be a businees partner.</span><span style="color: rgb(255, 255, 255); font-size: 16px; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px; white-space: break-spaces; background-color: var(--color-1);"> They are distributing a medicine of their own invention to the general public without permission and forcefully pushing it into people</span><span style="color: rgb(255, 255, 255); font-size: 16px; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px; white-space: break-spaces; background-color: var(--color-1);">. even they tried to push their suspicious medicine to police, in that case chief Mr. Rana sir took a sample from them for testing purpose. </span></p></span></p><ol class="scrollerInner_e2e187" aria-label="Messages in bcso" role="list" data-list-id="chat-messages" tabindex="0" style="margin: 0px; padding: 0px; border: 0px; font-size: 16px; vertical-align: baseline; list-style: none; min-height: 0px; overflow: hidden;"><li id="chat-messages-1243483349800976516-1303799036179910728" class="messageListItem_d5deea" aria-setsize="-1" style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; vertical-align: baseline; outline: none; position: relative;"><p id="message-content-1303799036179910728" class="markup_f8f345 messageContent_f9f2ca" style="text-align: justify; margin-top: 0px; margin-right: 0px; margin-bottom: 0px; margin-left: calc(-1*var(--custom-message-margin-left-content-cozy)); padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: var(--custom-message-margin-left-content-cozy); border: 0px; font-weight: inherit; font-style: inherit; font-size: 1rem; vertical-align: baseline; outline: 0px; line-height: 1.375rem; white-space: break-spaces; overflow-wrap: break-word; user-select: text; position: relative; overflow: hidden;"><span style="color: rgb(255, 255, 255); font-family: Tahoma, Geneva, sans-serif;"><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; vertical-align: baseline; outline: 0px;">The police handed over the sample to the EMS department for lab tests</span><span style="margin: 0px; padding: 0px; border: 0px; font-weight: inherit; font-style: inherit; vertical-align: baseline; outline: 0px;">.</span><span style="font-style: inherit; font-weight: inherit; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px;">After the lab test</span><span style="font-style: inherit; font-weight: inherit; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px;">, the EMS authority submits the report to the police</span><span style="font-style: inherit; font-weight: inherit; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px;">.  In the report</span><span style="font-style: inherit; font-weight: inherit; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px;">, they confirmed that the suspect medicine is morphine</span><span style="font-style: inherit; font-weight: inherit; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px;">, which is very harmful to the human body</span><span style="font-style: inherit; font-weight: inherit; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px;">. There is a risk of death due to its excessive use</span><span style="font-style: inherit; font-weight: inherit; margin: 0px; padding: 0px; border: 0px; vertical-align: baseline; outline: 0px;">.</span></span></p></li></ol><p><br></p><p><hr></p><p><strong style="color: rgb(255, 255, 255);">EVIDENCE:</strong></p><ul><li><font color="#ffffff">Report from Mount Jonah Hospital</font><br></li></ul><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>LOCATION OF SUBJECT: MRPD</strong><br></span></p><p><hr></p><p><span style="color: rgb(255, 255, 255);"><strong>AUTHORIZATION:</strong><br>This warrant authorizes the San Andreas Police Department to arrest Miss Quinzel<br></span></p><p><hr></p>', '["Promoting Illegal Morphine","Miss Quitnzel","Arrest Warrant"]', '["(200) Nh Rana","(320) Laizy Panda","(241) Bagha Robin","(301) Harry Dexter"]', '["MISS Quinzel","Jason Trujillo"]', '["https://files.catbox.moe/zoh5js.png","https://files.catbox.moe/33j6mb.png"]', '1730917084087', 'police'),
	(310, 'Laizy Panda', 'Criminal threat', 'F.I.R', '<p><strong>Date: 14-11-2024</strong><br><strong>Debrief :</strong> Today,&nbsp; Mr. ramo received criminal threat&nbsp; at richman .&nbsp; They told him to fight against them and they used slang.<br><strong>victim :</strong> ramo<br><strong>Contact info : </strong>6021891365<br><strong>Suspect : </strong><br><strong>1.</strong> toxic tanvir, contact info-6027176878, resident : Toxic mansion<br><strong>2.</strong> crimson<br><br></p>', '[]', '["(320) Laizy Panda","(101 | Arcan) Arcan Walker"]', '["RAMO  XD"]', '[]', '1731605229225', 'police');
